const resetPasswordLnkBtn=document.querySelector("#resetPasswordLnkBtn");resetPasswordLnkBtn.addEventListener("click",async()=>{const email=document.querySelector("#InputEmail");const btnText=document.querySelector("#btnText");const btnSpinner=document.querySelector("#btnSpinner");if(resetPasswordEmailForm.checkVisibility()){try{resetPasswordLnkBtn.disabled=true;btnText.classList.replace("d-block","d-none");btnSpinner.classList.replace("d-none","d-block");const res=await axios.post("/user/forgot_password",{email:email.value});window.location=res.data.redirect}catch(error){showToast({error:"Cannot Contact Server!"})}}});